import { useEffect, useState } from 'react'
import { api } from './api'
import { AgentTiles } from './components/AgentTiles'
import { ChecksTable } from './components/ChecksTable'
import { ComplianceCard } from './components/ComplianceCard'
import { DesignTabs } from './components/DesignTabs'
import { ModelViewer } from './components/ModelViewer'
import type { CheckResult, ComplianceCard as Card, DesignVariant } from './types'

export default function App() {
  const [health, setHealth] = useState<string>('checking…')
  const [card, setCard] = useState<Card | null>(null)
  const [results, setResults] = useState<CheckResult[]>([])
  const [designs, setDesigns] = useState<DesignVariant[]>([])

  useEffect(() => {
    api.health().then((h) => setHealth(h.status), () => setHealth('backend unreachable'))
    api.compliance().then(setCard, console.error)
    api.designs().then(setDesigns, console.error)
    api
      .seedCandidates()
      .then((cs) => Promise.all(cs.map(api.checks)))
      .then(setResults, console.error)
  }, [])

  return (
    <main>
      <header>
        <h1>AI Robot Redesign Engine</h1>
        <span className="muted">API: {health}</span>
      </header>
      <ModelViewer src="/cad/files/test_23.glb" />
      <div className="grid">
        <ComplianceCard card={card} />
        <AgentTiles />
      </div>
      <ChecksTable results={results} />
      <DesignTabs designs={designs} />
      <footer className="muted">Not legal advice. COTS questions: flag for counsel.</footer>
    </main>
  )
}
// TODO(owner 4): one tile per TinyFish run; embed each run's streaming_url and
// show ✅ verified / ⚠️ blocked / ❌ not found as results arrive. Label cached replays.
export function AgentTiles() {
  return (
    <section className="panel">
      <h2>Agent swarm</h2>
      <p className="muted">Live TinyFish tiles appear here.</p>
    </section>
  )
}
import type { CheckResult, ComplianceCard, DesignVariant, MotorCandidate, Robot } from './types'

const BASE = import.meta.env.VITE_API_URL ?? ''

async function req<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`${BASE}${path}`, {
    headers: { 'Content-Type': 'application/json' },
    ...init,
  })
  if (!res.ok) throw new Error(`${res.status} ${res.statusText}: ${path}`)
  return res.json() as Promise<T>
}

export const api = {
  health: () => req<{ status: string }>('/health'),
  robot: () => req<Robot>('/api/robot'),
  compliance: () => req<ComplianceCard>('/api/compliance'),
  seedCandidates: () => req<MotorCandidate[]>('/api/candidates/seed'),
  checks: (c: MotorCandidate) =>
    req<CheckResult>('/api/checks', { method: 'POST', body: JSON.stringify(c) }),
  designs: () => req<DesignVariant[]>('/api/designs'),
}
