    case 'run_progress': {
      const run = state.runs[ev.data.run_id]
      return run ? updateRun(state, run.runId, { steps: [...run.steps, ev.data.purpose] }) : state
    }
    case 'run_finished':
      return updateRun(state, ev.data.run_id, {
        outcome: ev.data.outcome,
        reason: ev.data.reason,
        live: ev.data.live,
      })
    case 'claim_verified':
